50: /// all keyspaces unchanged before retry succeeds at seq 1.
51: #[test]
52: fn cli_injected_batch_commit_failure_strict() -> TestResult {
53:     check_batch_failure(RuntimePolicy::Strict)?;
54:     Ok(())
55: }
56: 
57: #[test]
58: fn cli_injected_batch_commit_failure_journaled() -> TestResult {
59:     check_batch_failure(RuntimePolicy::Journaled)?;
60:     Ok(())
61: }
62: 
63: #[test]
64: fn cli_injected_batch_commit_failure_relaxed() -> TestResult {
65:     check_batch_failure(RuntimePolicy::Relaxed)?;
66:     Ok(())
67: }
68: 
69: fn check_batch_failure(policy: RuntimePolicy) -> TestResult {
70:     let (_dir, journal) = open_test_journal()?;
71:     let submission = make_submission(policy, 42)?;
72:     journal.fail_next_batch_commit_for_test();
73:     let result = journal.commit_run_submission(&submission, policy);
74:     assert!(
75:         matches!(&result, Err(JournalError::Fjall(fjall::Error::Io(error))) if error.kind() == std::io::ErrorKind::Other),
76:         "expected Fjall I/O error with Other kind, got: {result:?}"
77:     );
78:     assert_eq!(read_counter(&journal)?, None);
79:     verify_empty_journal(&journal)?;
80: 
81:     journal.commit_run_submission(&submission, policy)?;
82:     assert_eq!(read_counter(&journal)?, Some(1));
83:     verify_cli_submission_artifact_seq(&journal, vb_core::RunId::new(100), 1)?;
84:     Ok(())
85: }

