1: //! Raw journal snapshot test support for F1 duplicate and F2 reopen full-state checks.
2: 
3: use crate::FjallJournal;
4: 
5: type Rows = Vec<(Vec<u8>, Vec<u8>)>;
6: type Snapshot = [Rows; 8];
7: 
8: fn iterate_keyspace(
9:     rows: impl Iterator<Item = fjall::Guard>,
10: ) -> Result<Rows, Box<dyn std::error::Error>> {
11:     let mut result: Rows = Vec::new();
12:     for (i, guard) in rows.take(17).enumerate() {
13:         if i >= 16 {
14:             return Err("keyspace exceeds 16-row bound".into());
15:         }
16:         let (key, value) = guard.into_inner().map_err(|e| format!("into_inner: {e}"))?;
17:         result.push((key.to_vec(), value.to_vec()));
18:     }
19:     Ok(result)
20: }
21: 
22: pub(super) fn snapshot_journal(
23:     journal: &FjallJournal,
24: ) -> Result<Snapshot, Box<dyn std::error::Error>> {
25:     let artifact_acceptance = iterate_keyspace(journal.artifact_acceptance.iter())?;
26:     assert!(
27:         artifact_acceptance.len() <= 16,
28:         "artifact_acceptance exceeds bound"
29:     );
30: 
31:     let workflow_source = iterate_keyspace(journal.workflow_source.iter())?;
32:     assert!(workflow_source.len() <= 16, "workflow_source exceeds bound");
33: 
34:     let compiled_ir = iterate_keyspace(journal.compiled_ir.iter())?;
35:     assert!(compiled_ir.len() <= 16, "compiled_ir exceeds bound");
36: 
37:     let run_header = iterate_keyspace(journal.run_header.iter())?;
38:     assert!(run_header.len() <= 16, "run_header exceeds bound");
39: 
40:     let run_inputs = iterate_keyspace(journal.run_inputs.iter())?;
41:     assert!(run_inputs.len() <= 16, "run_inputs exceeds bound");
42: 
43:     let events = iterate_keyspace(journal.events.iter())?;
44:     assert!(events.len() <= 16, "events exceeds bound");
45: 
46:     let index_status = iterate_keyspace(journal.index_status.iter())?;
47:     assert!(index_status.len() <= 16, "index_status exceeds bound");
48: 
49:     let index_workflow = iterate_keyspace(journal.index_workflow.iter())?;
50:     assert!(index_workflow.len() <= 16, "index_workflow exceeds bound");
51: 
52:     Ok([
53:         artifact_acceptance,
54:         workflow_source,
55:         compiled_ir,
56:         run_header,
57:         run_inputs,
58:         events,
59:         index_status,
60:         index_workflow,
61:     ])
62: }

