140: /// Read the raw artifact acceptance counter from the journal.
141: pub(super) fn read_counter(journal: &FjallJournal) -> Result<Option<u64>, BoxError> {
142:     let Some(raw) = journal.artifact_acceptance.get(b"last_issued")? else {
143:         return Ok(None);
