7: use vb_core::action_pack::{ActionPack, CapabilityScopeSpec, RecoveryClass};
8: use vb_core::value::ConstValue;
9: use vb_core::workflow::{ResourceContract, WorkflowParts};
10: use vb_core::{
11:     Capability, CompiledNode, CompiledNodeKind, CompiledWorkflow, ConstIdx, RuntimePolicy, SlotIdx,
12:     StepIdx, WorkflowDigest,
13: };
14: 
15: type BoxError = Box<dyn std::error::Error>;
16: 
17: pub(super) type TestResult = Result<(), BoxError>;
18: 
19: /// Open a fresh test journal in a temporary directory.
20: pub(super) fn open_test_journal() -> Result<(tempfile::TempDir, FjallJournal), BoxError> {
21:     let dir = tempfile::tempdir()?;
22:     let journal = FjallJournal::open(dir.path(), None)?;
23:     Ok((dir, journal))
24: }
25: 
26: /// Build a minimal compiled workflow with no actions.
27: pub(super) fn minimal_workflow() -> Result<CompiledWorkflow, BoxError> {
28:     let mut parts = parts_from("test_minimal");
29:     parts.constants = Box::new([ConstValue::I64(42)]);
30:     parts.slot_count = 1;
31:     canonicalize_parts(&mut parts)?;
32:     Ok(CompiledWorkflow::try_from_parts(parts)?)
33: }
34: 
35: /// Build a compiled workflow containing one action invocation.
36: pub(super) fn action_workflow() -> Result<CompiledWorkflow, BoxError> {
37:     let mut parts = parts_from("test_action");
38:     parts.nodes = Box::new([set_node(), action_node(), finish_node(2, 1)]);
39:     parts.constants = Box::new([ConstValue::I64(42)]);
40:     parts.slot_count = 2;
41:     canonicalize_parts(&mut parts)?;
42:     Ok(CompiledWorkflow::try_from_parts(parts)?)
43: }
44: 
45: fn set_node() -> CompiledNode {
46:     CompiledNode {
47:         id: StepIdx::new(0),
48:         output: Some(SlotIdx::new(0)),
49:         next: Some(StepIdx::new(1)),
50:         on_error: None,
51:         error_slot: None,
