34:     fn validate_binding(&self) -> Result<(), JournalError> {
35:         self.validate_identities()?;
36:         crate::journal::verify_content_digest(&self.source.source, &self.source.digest.as_bytes())?;
37:         let workflow = crate::admission::verify_accepted_artifact(&self.artifact)?;
38:         self.inputs.validate_workflow(&workflow)?;
39:         if crate::admission::compute_policy_digest(&workflow)? != self.artifact.policy_digest {
40:             return Err(JournalError::PayloadDigestMismatch);
41:         }
42:         Ok(())
43:     }
44: 
45:     fn validate_identities(&self) -> Result<(), JournalError> {
46:         let digest = crate::admission::accepted_artifact_digest(&self.artifact)?;
47:         if digest != self.artifact.digest
48:             || digest != self.artifact.verification.digest
49:             || digest != self.inputs.artifact_digest()
50:             || self.header.run != self.inputs.run()
51:             || self.header.compiled_digest != self.inputs.workflow_digest()
52:             || self.source.digest != self.inputs.source_digest()
53:             || self.artifact.source_digest != self.inputs.workflow_digest()
54:         {
55:             return Err(JournalError::PayloadDigestMismatch);
56:         }
57:         Ok(())
58:     }
59: 
60:     fn validate_policy(&self, policy: RuntimePolicy) -> Result<(), JournalError> {
61:         if !matches!(
62:             policy,
63:             RuntimePolicy::Relaxed | RuntimePolicy::Journaled | RuntimePolicy::Strict
64:         ) {
65:             return Err(JournalError::AdmissionRequired);
66:         }
67:         if !self.artifact.required_capabilities.is_empty() {
68:             return Err(JournalError::CapabilityDenied);
69:         }
70:         crate::admission::verify_accepted_artifact_for_policy(&self.artifact, policy)?;
71:         Ok(())
72:     }
73: 
